import React from "react";
import { Link } from "react-router-dom";
import { useSelector, useDispatch } from "react-redux";
import { useState, useEffect } from "react";
import { DeleteEnquiry, GetAllEnquiry } from "../../src/reducer/EnquirySlice";
import Table from "@mui/material/Table";
import TableBody from "@mui/material/TableBody";
import TableCell from "@mui/material/TableCell";
import TableContainer from "@mui/material/TableContainer";
import TableHead from "@mui/material/TableHead";
import TableRow from "@mui/material/TableRow";
import TableSortLabel from "@mui/material/TableSortLabel";
import Paper from "@mui/material/Paper";
import { useNavigate } from "react-router-dom";
import Swal from "sweetalert2";
import TextField from "@mui/material/TextField";
import InputAdornment from "@mui/material/InputAdornment";
import FormControl from "@mui/material/FormControl";
import Select from "@mui/material/Select";
import { EnquiryStatus } from "../../src/reducer/EnquirySlice";
import MenuItem from "@mui/material/MenuItem";
import { ImportEnquirys } from "../../src/reducer/EnquirySlice";
import IconButton from "@mui/material/IconButton";
import ClearIcon from "@mui/icons-material/Clear";
import Dialog from "@mui/material/Dialog";
import DialogActions from "@mui/material/DialogActions";
import DialogContent from "@mui/material/DialogContent";
import Box from "@mui/material/Box";
import Button from "@mui/material/Button";
import VisibilityIcon from "@mui/icons-material/Visibility";
import AssignmentIcon from "@mui/icons-material/Assignment";
import axios from "axios";
import { baseurl } from "../Basurl/Baseurl";
import { Autocomplete, OutlinedInput, Pagination, Stack } from "@mui/material";
import { toast, ToastContainer } from "react-toastify";
import { usePDF } from "react-to-pdf";
import { GetAllHositalData } from "../reducer/HospitalSlice";
import { Field } from "formik";
import Tabs from "@mui/material/Tabs";
import Tab from "@mui/material/Tab";
import { testForms } from "../reducer/FormsEnquiry";
export default function Inquiry() {
  const { toPDF, targetRef } = usePDF({ filename: "inquiry.pdf" });
  const role = localStorage.getItem("Role");
  const navigate = useNavigate();
  const [note, setNote] = useState("");
  const [date, setDate] = useState();
  const [open2, setOpen2] = React.useState(false);
  const [fullWidth, setFullWidth] = React.useState(true);
  const [maxWidth, setMaxWidth] = React.useState("sm");
  const [open3, setOpen3] = React.useState(false);
  const [open9, setOpen9] = React.useState(false);
  const [filterValue, setFilterValue] = useState("");
  const [page, setPage] = useState(0);
  const [selectedImage, setSelectedImage] = useState(null);
  const [orderDirection, setOrderDirection] = useState("asc");
  const [orderBy, setOrderBy] = useState("");
  const [rowsPerPage, setRowsPerPage] = useState(10);
  const [rows, setRows] = useState([]);
  const [report, setReport] = useState([]);
  const [searchApiData, setSearchApiData] = useState([]);
  const dispatch = useDispatch();
  const { testForms: formData } = useSelector((state) => state.testForms);
  const { Enquiry, loading, error } = useSelector((state) => state.Enquiry);
  const { hospital } = useSelector((state) => state.hospital);
  const [tabValue, setTabValue] = useState(0);

  const handleTabChange = (event, newValue) => {
    setTabValue(newValue);
  };
  useEffect(() => {
    dispatch(testForms());
  }, [dispatch]);

  const airAmbulanceData = formData?.data?.air_ambulance || [];
  const ambulanceData = formData?.data?.ambulance_requests || [];
  const treatmentData = formData?.data?.get_treatment_estimate || [];
  useEffect(() => {
    dispatch(GetAllHositalData());
    console.log(error, hospital);
  }, [dispatch]);
  const [seekerStatus, setSeekerStatus] = React.useState({});
  const [blogErr, setBlogErr] = useState(false);
  const [pdfRowLimit, setPdfRowLimit] = useState(false);
  console.log(Enquiry);
  const [enqId, setEnqId] = useState("");
  const handleClose3 = () => {
    setOpen3(false);
  };
  const handleClose2 = () => {
    setOpen2(false);
  };
  const handleClose2wew = () => {
    setOpen9(false);
  };
  const handleClickOpen2modla = () => {
    setOpen9(true);
  };
  const handleClickOpen2 = (e, enq) => {
    setOpen2(true);
    setEnqId(enq);
  };
  const handleClickOpen3 = (e) => {
    setOpen3(true);
  };
  useEffect(() => {
    dispatch(GetAllEnquiry());
    console.log(error, Enquiry);
  }, [dispatch]);
  useEffect(() => {
    if (Array.isArray(Enquiry) && Enquiry.length > 0) {
      const filtered = Enquiry.filter(
        (item) => item.Enquiry_status !== "Confirmed",
      );
      setRows(filtered);
      setSearchApiData(filtered);
    } else {
      setRows([]);
      setSearchApiData([]);
    }
  }, [Enquiry]);

  console.log(searchApiData);
  const handleChangePage = (event, newPage) => {
    setPage(newPage);
  };
  const EditButton = (e, id) => {
    navigate("/Admin/edit-Enquiry", {
      state: {
        enquiryId: id,
      },
    });
  };
  const ViewDetail = (e, id) => {
    navigate("/Admin/Enquiry-Detail", {
      state: {
        enquiryId: id,
      },
    });
  };

  const handleChange = async (event, id) => {
    console.log(event, id);
    const { value } = event.target;

    // confirmation alert
    const result = await Swal.fire({
      title: "Are you sure?",
      text: "Do you really want to update the status?",
      icon: "warning",
      showCancelButton: true,
      confirmButtonText: "Yes, update it!",
      cancelButtonText: "Cancel",
      reverseButtons: true,
    });
    if (!result.isConfirmed) {
      return;
    }
    setSeekerStatus((prev) => ({
      ...prev,
      [id]: value,
    }));
    try {
      await dispatch(EnquiryStatus({ id, status: Number(value) })).unwrap();
      Swal.fire("Success!", "Status updated successfully!", "success");
      setRows((prevRows) => prevRows.filter((item) => item.enquiryId !== id));
      dispatch(GetAllEnquiry());
    } catch (err) {
      Swal.fire("Error!", err?.message || "An error occurred", "error");
    }
  };
  const handleSampleFile = async () => {
    try {
      const response = await axios.get(`${baseurl}export_enquiries`, {
        headers: {
          Authorization: `Bearer ${localStorage.getItem("token")}`,
        },
        responseType: "blob",
      });
      const url = window.URL.createObjectURL(new Blob([response.data]));
      const link = document.createElement("a");
      link.href = url;
      link.setAttribute("download", "Sample Enquiry.xlsx");
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
      Swal.fire({
        icon: "success",
        title: "Download Complete",
        text: "Sample_Enquiry.xlsx has been downloaded successfully!",
        timer: 3000,
        showConfirmButton: false,
      });

      return response.data;
    } catch (err) {
      console.error(
        "Error downloading the sample file:",
        err.response?.data?.message || err.message,
      );

      Swal.fire({
        icon: "error",
        title: "Download Failed",
        text: err.response?.data?.message || "Something went wrong!",
      });

      throw err;
    }
  };
  const handleHospitalChange = (event, newValue) => {
    setReport((prev) => ({ ...prev, hospital: newValue }));
  };
  const handleImportFile = async (e) => {
    e.preventDefault();
    if (!selectedImage) {
      toast.error("Please select a file before uploading.");
      return;
    }
    const formData = new FormData();
    formData.append("file", selectedImage);
    for (let pair of formData.entries()) {
      console.log(`${pair[0]}:`, pair[1]);
    }
    try {
      const result = await dispatch(ImportEnquirys(formData)).unwrap();
      setOpen3(false);
      dispatch(GetAllEnquiry());
      Swal.fire("Success!", `${result.message}`, "success");
    } catch (err) {
      console.log(err);
      setOpen3(false);
      Swal.fire("Error!", err?.error || "An error occurred", "error");
    }
  };
  const handleFilter = (event) => {
    const value = event.target.value.toLowerCase().trim();
    setFilterValue(event.target.value);
    setPage(0);

    if (!value) {
      setRows(searchApiData);
      return;
    }

    const filterResult = searchApiData.filter((item) => {
      return (
        String(item.enquiryId || "")
          .toLowerCase()
          .includes(value) ||
        String(item.email || "")
          .toLowerCase()
          .includes(value) ||
        String(item.country || "")
          .toLowerCase()
          .includes(value) ||
        String(item.name || "")
          .toLowerCase()
          .includes(value) ||
        String(item.age || "")
          .toLowerCase()
          .includes(value) ||
        String(item.emergency_contact || "")
          .toLowerCase()
          .includes(value) ||
        String(item.disease_name || "")
          .toLowerCase()
          .includes(value)
      );
    });

    setRows(filterResult);
  };
  // const handleFilter = (event) => {
  //   const value = event.target.value.toLowerCase();
  //   setFilterValue(event.target.value);
  //   setPage(0); // ⭐ RESET PAGE

  //   if (value === "") {
  //     setRows(searchApiData);
  //     return;
  //   }
  //   const filterResult = searchApiData.filter((item) => {
  //     const enquiryId = item.enquiryId?.toLowerCase() || "";
  //     const email = item.email?.toLowerCase() || "";
  //     const country = item.country?.toLowerCase() || "";
  //     const name = item.name?.toLowerCase() || "";
  //     const age = item.age?.toString().toLowerCase() || "";
  //     const contact = item.emergency_contact?.toString().toLowerCase() || "";
  //     const disease = item.disease_name?.toLowerCase() || "";
  //     return (
  //       enquiryId.includes(value) ||
  //       email.includes(value) ||
  //       country.includes(value) ||
  //       name.includes(value) ||
  //       age.includes(value) ||
  //       contact.includes(value) ||
  //       disease.includes(value)
  //     );
  //   });
  //   setRows(filterResult);
  // };
  const handleClearFilter = () => {
    setFilterValue("");
    setRows(searchApiData);
    setPage(0); // ⭐ RESET PAGE
  };
  useEffect(() => {
    setPage(0);
  }, [rows]);
  const [age, setAge] = React.useState("");
  const handleChange3 = (event) => {
    setAge(event.target.value);
  };
  const handleNotesdata = (e) => {
    e.preventDefault();
    setBlogErr({
      note: false,
      date: false,
    });
    if (!note) {
      setBlogErr((prevState) => ({ ...prevState, note: true }));
    }
    if (!date) {
      setBlogErr((prevState) => ({ ...prevState, date: true }));
    }
    if (!note || !date) {
      return;
    }
    axios
      .post(`${baseurl}add_notes/${enqId}`, {
        note: note,
        date: date,
      })
      .then((response) => {
        console.log(response);
        setBlogErr(false);
        if (response.status === 200) {
          setOpen2(false);
          Swal.fire("Success", "Notes added successfully!", "success");
        }
        setNote("");
        setDate("");
      })
      .catch((error) => {
        setOpen2(false);
        console.log(error);
        Swal.fire("Error", `${error?.response?.data?.message}`, "error");
      });
  };
  const handledelete = (e, patientId) => {
    console.log(e);
    const swalWithBootstrapButtons = Swal.mixin({
      customClass: {
        confirmButton: "btn btn-success",
        cancelButton: "btn btn-danger",
      },
      buttonsStyling: false,
    });
    swalWithBootstrapButtons
      .fire({
        title: "Are you sure?",
        icon: "warning",
        showCancelButton: true,
        confirmButtonText: "Yes, delete it!",
        cancelButtonText: "No, cancel!",
        reverseButtons: true,
      })
      .then((result) => {
        if (result.isConfirmed) {
          dispatch(DeleteEnquiry({ id: e }))
            .unwrap()
            .then(() => {
              return dispatch(GetAllEnquiry());
            })
            .then((newData) => {
              Swal.fire("Deleted!", "Patient has been deleted.", "success");
              setRows(newData.payload);
            })
            .catch((err) => {
              Swal.fire("Error!", err?.message || "An error occurred", "error");
            });
        } else if (result.dismiss === Swal.DismissReason.cancel) {
          swalWithBootstrapButtons.fire({
            title: "Cancelled",
            icon: "error",
          });
        }
      });
  };
  const donloadpdf = async () => {
    const maxRows = rows.length || 1;
    Swal.fire({
      title: "Enter number of rows for PDF",
      input: "number",
      inputLabel: `Choose between 1 and ${maxRows}`,
      inputAttributes: {
        min: "1",
        max: maxRows.toString(),
        step: "1",
      },
      inputValue: rowsPerPage,
      showCancelButton: true,
      confirmButtonText: "Generate PDF",
    }).then((result) => {
      if (result.isConfirmed) {
        const userInput = parseInt(result.value, 10);
        if (isNaN(userInput) || userInput < 1 || userInput > maxRows) {
          Swal.fire(
            "Invalid entry",
            `Please enter a number between 1 and ${maxRows}`,
            "error",
          );
          return;
        }
        setPdfRowLimit(userInput);
        setTimeout(() => {
          toPDF();
          setPdfRowLimit(null); // reset to normal view
        }, 300);
      }
    });
  };

  const handleRequestSort = (property) => {
    const isAsc = orderBy === property && orderDirection === "asc";
    const direction = isAsc ? "desc" : "asc";

    setOrderDirection(direction);
    setOrderBy(property);

    const sortedData = [...rows].sort((a, b) => {
      if (a[property] < b[property]) {
        return direction === "asc" ? -1 : 1;
      }
      if (a[property] > b[property]) {
        return direction === "asc" ? 1 : -1;
      }
      return 0;
    });

    setRows(sortedData);
  };
  useEffect(() => {
    let filtered = [];

    switch (tabValue) {
      case 0:
        filtered = normalizeData(Enquiry || [], "enquiry");
        break;

      case 1:
        filtered = normalizeData(ambulanceData, "ambulance");
        break;

      case 2:
        filtered = normalizeData(airAmbulanceData, "air");
        break;

      case 3:
        filtered = normalizeData(treatmentData, "treatment");
        break;

      default:
        filtered = [];
    }

    setRows(filtered);
    setSearchApiData(filtered);
  }, [tabValue, Enquiry, formData]);
  const normalizeData = (data, type) => {
    return data.map((item) => ({
      enquiryId: item.enquiryId || item.id,
      name: item.name || item.first_name,
      email: item.email,
      country: item.country || item.city,
      emergency_contact: item.emergency_contact || item.phone,
      disease_name: item.disease_name || item.services?.replaceAll("_", " "),
      Enquiry_status: item.Enquiry_status || item.status,
      raw: item, // full data for view popup
    }));
  };
  return (
    <>
      <div className="page-wrapper">
        <div className="content">
          <Box sx={{ borderBottom: 1, borderColor: "divider", mb: 2 }}>
            <Tabs value={tabValue} onChange={handleTabChange}>
              <Tab label="Enquiry" />
              <Tab label="Ambulance Service" />
              <Tab label="Air Medical Escort" />
              <Tab label="Treatment Estimate" />
            </Tabs>
          </Box>
          <div className="row">
            <div className="col-md-12">
              <div className="country-top">
                <div className="">
                  <h4 className="page-title mb-0">
                    {tabValue === 0
                      ? "Enquiries"
                      : tabValue === 1
                        ? "Ambulance Service"
                        : tabValue === 2
                          ? "Air Medical escort"
                          : tabValue === 3
                            ? "Treatment Estimate"
                            : ""}
                  </h4>
                </div>
                <div className="search-btn-main">
                  <div className="mr-3">
                    <TextField
                      sx={{ width: "100%" }}
                      className="field-count"
                      label="Search"
                      id="outlined-required"
                      size="small"
                      value={filterValue}
                      onChange={handleFilter} // Pass event directly
                      InputLabelProps={{ shrink: true }}
                      InputProps={{
                        endAdornment: (
                          <InputAdornment position="end">
                            {filterValue && (
                              <IconButton
                                onClick={handleClearFilter}
                                edge="end"
                                className="input-set"
                              >
                                <ClearIcon />
                              </IconButton>
                            )}
                          </InputAdornment>
                        ),
                      }}
                    />
                  </div>
                  {tabValue === 0 ? (
                    <div className="">
                      <div className="table-top-btn">
                        <Link to="/Admin/add-Enquiry" className="add-button">
                          <span>
                            <i className="fa fa-plus"></i>
                          </span>
                          New Enquiry
                        </Link>
                        <button
                          onClick={(e) => handleClickOpen3(e)}
                          className="add-button"
                        >
                          <span>
                            <i className="fa fa-file-excel-o mx-1"></i>
                          </span>{" "}
                          Import File
                        </button>
                        <button
                          onClick={handleSampleFile}
                          className="add-button"
                        >
                          <span>
                            <i className="fa fa-file"></i>
                          </span>
                          Export File
                        </button>
                        {role === "Admin" ? (
                          <button onClick={donloadpdf} className="add-button">
                            <span>
                              <i className="fa fa-file-pdf-o"></i>
                            </span>
                            pdf
                          </button>
                        ) : (
                          ""
                        )}
                      </div>
                    </div>
                  ) : (
                    ""
                  )}
                </div>
              </div>
            </div>
          </div>

          <div className="main_content">
            <div className="row">
              <div className="col-md-12">
                <div className="table-responsive">
                  <TableContainer
                    component={Paper}
                    style={{ overflowX: "auto" }}
                    ref={targetRef}
                  >
                    <Table
                      stickyHeader
                      aria-label="sticky table"
                      className="table-no-card"
                    >
                      <TableHead>
                        <TableRow>
                          <TableCell>Sr.No.</TableCell>
                          {tabValue === 0 ? (
                            <TableCell>
                              <TableSortLabel
                                active={orderBy === "enquiryId"}
                                direction={
                                  orderBy === "enquiryId"
                                    ? orderDirection
                                    : "asc"
                                }
                                onClick={() => handleRequestSort("enquiryId")}
                              >
                                Enquiry IDs
                              </TableSortLabel>
                            </TableCell>
                          ) : (
                            ""
                          )}

                          <TableCell>
                            <TableSortLabel
                              active={orderBy === "name"}
                              direction={
                                orderBy === "name" ? orderDirection : "asc"
                              }
                              onClick={() => handleRequestSort("name")}
                            >
                              Name
                            </TableSortLabel>
                          </TableCell>
                          {/* <TableCell>Email</TableCell> */}
                          <TableCell>
                            <TableSortLabel
                              active={orderBy === "country"}
                              direction={
                                orderBy === "country" ? orderDirection : "asc"
                              }
                              onClick={() => handleRequestSort("country")}
                            >
                              Country
                            </TableSortLabel>
                          </TableCell>
                          <TableCell>
                            <TableSortLabel
                              active={orderBy === "emergency_contact"}
                              direction={
                                orderBy === "emergency_contact"
                                  ? orderDirection
                                  : "asc"
                              }
                              onClick={() =>
                                handleRequestSort("emergency_contact")
                              }
                            >
                              Contact
                            </TableSortLabel>
                          </TableCell>
                          <TableCell>Disease name</TableCell>
                          <TableCell>Status</TableCell>
                          {tabValue === 0 ? (
                            <>
                              <TableCell>Actions</TableCell>
                              <TableCell>Notes</TableCell>
                            </>
                          ) : (
                            ""
                          )}
                        </TableRow>
                      </TableHead>
                      <TableBody>
                        {(pdfRowLimit
                          ? rows.slice(0, pdfRowLimit)
                          : rows.slice(
                              page * rowsPerPage,
                              page * rowsPerPage + rowsPerPage,
                            )
                        ).length > 0 ? (
                          (pdfRowLimit
                            ? rows.slice(0, pdfRowLimit)
                            : rows.slice(
                                page * rowsPerPage,
                                page * rowsPerPage + rowsPerPage,
                              )
                          ).map((info, i) => (
                            <TableRow
                              role="checkbox"
                              tabIndex={-1}
                              key={info.code}
                            >
                              <TableCell>
                                {pdfRowLimit
                                  ? i + 1
                                  : page * rowsPerPage + i + 1}
                              </TableCell>
                              {tabValue === 0 ? (
                                <TableCell>{info.enquiryId}</TableCell>
                              ) : (
                                ""
                              )}
                              <TableCell
                                style={{ cursor: "pointer" }}
                                onClick={(e) =>
                                  tabValue === 0 &&
                                  ViewDetail(e, info.enquiryId)
                                }
                              >
                                {info.name}
                              </TableCell>
                              {/* <TableCell>{info.email}</TableCell> */}
                              <TableCell>{info.country}</TableCell>
                              <TableCell>{info.emergency_contact}</TableCell>
                              {/* <TableCell title={info.disease_name}> */}
                              <TableCell title={info.disease_name}>
                                {info.disease_name?.length > 10
                                  ? info.disease_name.slice(0, 10) + "..."
                                  : info.disease_name}
                              </TableCell>
                              <TableCell>
                                <FormControl
                                  sx={{ m: 1, minWidth: 120 }}
                                  size="small"
                                  className="cont-main"
                                >
                                  <Select
                                    value={
                                      seekerStatus[info.enquiryId]
                                        ? seekerStatus[info.enquiryId]
                                        : info.Enquiry_status === "Confirmed"
                                          ? "1"
                                          : info.Enquiry_status === "Hold"
                                            ? "2"
                                            : info.Enquiry_status ===
                                                "Follow-Up"
                                              ? "3"
                                              : info.Enquiry_status === "Dead"
                                                ? "4"
                                                : ""
                                    }
                                    onChange={(e) =>
                                      handleChange(e, info.enquiryId)
                                    }
                                    displayEmpty
                                    inputProps={{
                                      "aria-label": "Without label",
                                    }}
                                    className="status-direct"
                                    renderValue={(selected) => {
                                      switch (selected) {
                                        case "1":
                                          return "Confirmed";
                                        case "2":
                                          return "Hold";
                                        case "3":
                                          return "Follow-up";
                                        case "4":
                                          return "Closed";
                                        default:
                                          return "Pending";
                                      }
                                    }}
                                  >
                                    <MenuItem value="1">Confirmed</MenuItem>
                                    <MenuItem value="2">Hold</MenuItem>
                                    <MenuItem value="3">Follow-up</MenuItem>
                                    <MenuItem value="4">Closed</MenuItem>
                                  </Select>
                                </FormControl>
                              </TableCell>
                              {tabValue === 0 ? (
                                <>
                                  <TableCell className="action-icon">
                                    <VisibilityIcon
                                      className="eye-icon"
                                      onClick={(e) =>
                                        ViewDetail(e, info.enquiryId)
                                      }
                                    />
                                    <i
                                      className="fa-solid fa-pen-to-square"
                                      onClick={(e) =>
                                        EditButton(e, info.enquiryId)
                                      }
                                    ></i>
                                    {localStorage.getItem("Role") ===
                                      "Admin" && (
                                      <i
                                        className="fa-solid fa-trash"
                                        onClick={() => handledelete(info)}
                                      ></i>
                                    )}
                                  </TableCell>
                                  <TableCell className="action-icon">
                                    <i
                                      className="fa-solid fa-notes-medical"
                                      onClick={(e) =>
                                        handleClickOpen2(e, info.enquiryId)
                                      }
                                    ></i>
                                  </TableCell>
                                </>
                              ) : (
                                ""
                              )}
                            </TableRow>
                          ))
                        ) : (
                          <TableRow>
                            <TableCell colSpan={11}>
                              <div className="flex justify-center py-4">
                                <p className="text-center text-gray-500">
                                  No Data Found
                                </p>
                              </div>
                            </TableCell>
                          </TableRow>
                        )}
                      </TableBody>
                    </Table>
                    {!pdfRowLimit && (
                      <Stack spacing={2}>
                        <Pagination
                          className="page-nation"
                          count={Math.ceil(rows.length / rowsPerPage)}
                          page={page + 1}
                          onChange={(event, value) => setPage(value - 1)}
                          color="primary"
                        />
                      </Stack>
                    )}
                  </TableContainer>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
      <React.Fragment>
        <Dialog
          fullWidth={fullWidth}
          maxWidth={maxWidth}
          open={open3}
          onClose={handleClose3}
        >
          <div className="main-card-header">
            <div className="note-hd">
              <h6>Import Excel File</h6>
            </div>
            <div className="cross-icon" onClick={handleClose3}>
              <i class="fa-solid fa-xmark"></i>
            </div>
          </div>
          <DialogContent className="main-box">
            <Box
              noValidate
              component="form"
              sx={{
                display: "flex",
                flexDirection: "column",
                width: "fit-content",
              }}
              className="contact-form"
            >
              <Box>
                <form id="contact-form" className="contact-form">
                  <div className="field-set">
                    <label>
                      Choose File<span className="text-danger">*</span>
                    </label>
                    <input
                      className="form-control"
                      type="file"
                      id="fileSelect"
                      accept=".xlsx, .xls, .csv"
                      onChange={(event) => {
                        const file = event.target.files[0];
                        console.log("Selected file:", file);
                        setSelectedImage(file);
                      }}
                    />
                  </div>
                  <DialogActions className="submit-main">
                    <Button
                      type="submit"
                      variant="contained"
                      onClick={(e) => handleImportFile(e)}
                    >
                      Submit
                    </Button>
                  </DialogActions>
                </form>
              </Box>
            </Box>
          </DialogContent>
        </Dialog>
      </React.Fragment>
      <div
        id="delete_appointment"
        className="modal fade delete-modal"
        role="dialog"
      >
        <div className="modal-dialog modal-dialog-centered">
          <div className="modal-content">
            <div className="modal-body text-center">
              <img src="assets/img/sent.png" alt="" width="50" height="46" />
              <h3>Are you sure want to delete this Appointment?</h3>
              <div className="m-t-20">
                {" "}
                <a href="#" className="btn btn-white" data-dismiss="modal">
                  Close
                </a>
                <button type="submit" className="btn btn-danger">
                  Delete
                </button>
              </div>
            </div>
          </div>
        </div>
      </div>
      <React.Fragment>
        <Dialog
          fullWidth={fullWidth}
          maxWidth={maxWidth}
          open={open9}
          onClose={handleClose2wew}
        >
          <div className="main-card-header">
            <div className="note-hd">
              <h6>Add Hospitals</h6>
            </div>
            <div className="cross-icon" onClick={handleClose2wew}>
              <i class="fa-solid fa-xmark"></i>
            </div>
          </div>
          <DialogContent className="main-box">
            <Box
              noValidate
              component="form"
              sx={{
                display: "flex",
                flexDirection: "column",
                width: "fit-content",
              }}
              className="contact-form"
            >
              <Box>
                <form id="contact-form">
                  <div className="col-sm-12">
                    <div className="field-set">
                      <label>
                        Select Hospital<span className="text-danger">*</span>
                      </label>
                      <Autocomplete
                        multiple
                        options={
                          hospital && hospital.length > 0
                            ? hospital.map((h) => h.name)
                            : []
                        }
                        value={report.hospital || []}
                        onChange={handleHospitalChange}
                        renderInput={(params) => (
                          <TextField
                            {...params}
                            placeholder="Search & Select Hospital"
                            variant="outlined"
                            size="small"
                          />
                        )}
                      />
                    </div>
                  </div>
                  <DialogActions className="submit-main">
                    <Button
                      type="submit"
                      variant="contained"
                      onClick={handleNotesdata}
                    >
                      Submit
                    </Button>
                  </DialogActions>
                </form>
              </Box>
            </Box>
          </DialogContent>
        </Dialog>
        <ToastContainer />
      </React.Fragment>
      <React.Fragment>
        <Dialog
          fullWidth={fullWidth}
          maxWidth={maxWidth}
          open={open2}
          onClose={handleClose2}
        >
          <div className="main-card-header">
            <div className="note-hd">
              <h6>Create Notes</h6>
            </div>
            <div className="cross-icon" onClick={handleClose2}>
              <i class="fa-solid fa-xmark"></i>
            </div>
          </div>
          <DialogContent className="main-box">
            <Box
              noValidate
              component="form"
              sx={{
                display: "flex",
                flexDirection: "column",
                width: "fit-content",
              }}
              className="contact-form"
            >
              <Box>
                <form id="contact-form">
                  <div className="field-set">
                    <label>
                      Notes<span className="text-danger">*</span>
                    </label>
                    <textarea
                      id="w3review"
                      name="discussionNotes"
                      rows="4"
                      cols="50"
                      className="form-control"
                      placeholder="Note"
                      onChange={(e) => setNote(e.target.value)}
                      value={note}
                    />
                    <span style={{ color: "red" }}>
                      {blogErr && !note ? "Please Enter Your  note" : ""}
                    </span>
                  </div>
                  <div className="field-set">
                    <label>
                      Date<span className="text-danger">*</span>
                    </label>
                    <input
                      type="date"
                      id="birthday"
                      name="date"
                      placeholder="Date"
                      className="form-control"
                      onChange={(e) => setDate(e.target.value)}
                      value={date}
                      min={new Date().toISOString().split("T")[0]}
                    />
                    <span style={{ color: "red" }}>
                      {blogErr && !date ? "Please Enter Your  date" : ""}
                    </span>
                  </div>
                  <DialogActions className="submit-main">
                    <Button
                      type="submit"
                      variant="contained"
                      onClick={handleNotesdata}
                    >
                      Submit
                    </Button>
                  </DialogActions>
                </form>
              </Box>
            </Box>
          </DialogContent>
        </Dialog>
        <ToastContainer />
      </React.Fragment>
    </>
  );
}
